function closeDrawer(){document.body.dataset.drawer='';document.getElementById('toggleTools').setAttribute('aria-expanded','false');document.getElementById('toggleInspector').setAttribute('aria-expanded','false');if(typeof resetCanvasView==='function')resetCanvasView();if(typeof scheduleLayout==='function')scheduleLayout()}for(const id of ['closeTools','closeInspector']){const button=document.getElementById(id);if(button)button.onclick=closeDrawer}document.addEventListener('pointerdown',()=>{lastPointer=performance.now()},true);document.addEventListener('focusin',e=>{if(performance.now()-lastPointer>300&&enabled()&&control(e.target)&&document.body.dataset.drawer)closeDrawer()});
